// All privileged operations live here. Browser bundles contain only the public key.
declare const EdgeRuntime:{waitUntil(task:Promise<unknown>):void};
const env=(name:string)=>Deno.env.get(name)||'';
const root=env('SUPABASE_URL');
const key=env('LOVEKOALA_SERVICE_KEY')||env('SUPABASE_SERVICE_ROLE_KEY');
const origins=new Set(['https://lovekoala.com.br','https://www.lovekoala.com.br',env('SITE_URL'),...env('ALLOWED_ORIGINS').split(',')].map(s=>s.trim().replace(/\/$/,'')).filter(Boolean));
const encoder=new TextEncoder();
class Fault extends Error{constructor(public status:number,public code:string,message:string){super(message);}}
const fail=(status:number,code:string,message:string):never=>{throw new Fault(status,code,message);};
const uuid=(v:unknown)=>typeof v==='string'&&/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/i.test(v);
const digest=async(s:string)=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',encoder.encode(s)))).map(x=>x.toString(16).padStart(2,'0')).join('');
const secretToken=()=>Array.from(crypto.getRandomValues(new Uint8Array(32))).map(x=>x.toString(16).padStart(2,'0')).join('');
function text(v:unknown,max:number,required=false){if(typeof v!=='string'||v.length>max||required&&!v.trim())fail(400,'INVALID_CONTENT','Confira os campos do seu presente.');return (v as string).trim();}
function headers(origin:string|null){return {'Content-Type':'application/json','Cache-Control':'no-store','Vary':'Origin',...(origin&&origins.has(origin)?{'Access-Control-Allow-Origin':origin}:{}),'Access-Control-Allow-Headers':'content-type,apikey,x-edit-token,authorization','Access-Control-Allow-Methods':'POST,OPTIONS','X-Content-Type-Options':'nosniff'};}
function allowedOrigin(req:Request){const origin=req.headers.get('origin');if(!origin||!origins.has(origin))fail(403,'ORIGIN_DENIED','Este endereço não está autorizado a criar presentes.');return origin;}
async function db(path:string,method='GET',body?:unknown){
 const response=await fetch(root+'/rest/v1/'+path,{method,headers:{apikey:key,Authorization:'Bearer '+key,'Content-Type':'application/json',Prefer:method==='POST'?'return=representation'+(path.includes('on_conflict=')?',resolution=ignore-duplicates':''):'return=representation'},body:body===undefined?undefined:JSON.stringify(body),signal:AbortSignal.timeout(18000)});
 const data=await response.json().catch(()=>null);if(!response.ok){const m=String(data?.message||'');if(m.includes('PROPOSAL_CONFLICT'))fail(409,'PROPOSAL_CONFLICT','Esse dado mudou depois da proposta. Peça uma proposta atualizada.');if(m.includes('PROPOSAL_EXPIRED')||m.includes('PROPOSAL_NOT_FOUND'))fail(409,'PROPOSAL_EXPIRED','A proposta venceu, foi descartada ou não pertence a esta conta.');if(m.includes('CHECKOUT_EMAIL_REQUIRED'))fail(403,'CHECKOUT_EMAIL_REQUIRED','Entre ou crie uma conta com o mesmo e-mail informado no pagamento e confirme esse endereço.');if(m.includes('RESUME_INVALID'))fail(403,'RESUME_INVALID','Esse link de retomada já foi usado ou venceu. Use seu acesso privado ou entre na sua conta.');if(m.includes('GIFT_OWNER'))fail(403,'GIFT_OWNER','Este presente já está vinculado a outra conta.');if(m.includes('AI_SCENE_LOCKED'))fail(409,'AI_SCENE_LOCKED','Essa cena já está em criação ou foi concluída. Escolha outra das quatro cenas.');if(m.includes('AI_SCENE_REQUIRED'))fail(400,'AI_SCENE_REQUIRED','Prepare a cena com o Koala antes de gerar.');if(m.includes('AI_BUSY'))fail(409,'AI_BUSY','Já há uma imagem sendo criada. Aguarde para iniciar a próxima.');if(m.includes('CLUB_LIMIT'))fail(409,'CLUB_LIMIT','Você já usou os presentes deste mês. A próxima mensalidade libera novas criações.');if(m.includes('CLUB_EXISTS'))fail(409,'CLUB_EXISTS','Você já tem o Clube. Use um dos seus presentes disponíveis na sua conta.');if(m.includes('CLUB_INACTIVE'))fail(402,'CLUB_INACTIVE','Renove o Clube para liberar novos presentes.');if(m.includes('EDIT_EXPIRED'))fail(403,'EDIT_EXPIRED','As 24 horas deste presente terminaram. O acesso e a edição foram encerrados.');if(m.includes('PAYMENT_REQUIRED'))fail(402,'PAYMENT_REQUIRED','Confirme o pagamento para publicar.');if(m.includes('PLAN_INCOMPATIBLE')||m.includes('PHOTO_LIMIT')||m.includes('IMAGE_LIMIT'))fail(400,'PLAN_LIMIT','Este plano não comporta o conteúdo escolhido.');if(m.includes('ORDER_PENDING'))fail(409,'ORDER_PENDING','Já há um pagamento em andamento. Confira a cobrança atual antes de trocar o plano ou o meio de pagamento.');if(m.includes('AUTOMATIC_SUBSCRIPTION'))fail(409,'AUTOMATIC_SUBSCRIPTION','Esta assinatura já renova automaticamente pelo cartão.');if(m.includes('RENEWAL_NOT_DUE'))fail(409,'RENEWAL_NOT_DUE','A renovação fica disponível nos 7 dias anteriores ao vencimento.');if(m.includes('ALREADY_PAID'))fail(409,'ALREADY_PAID','Este presente já foi pago. Atualize a página para continuar.');if(data?.code==='23505')fail(409,'ALREADY_EXISTS','Este endereço já foi escolhido. Tente acrescentar uma data ou um detalhe.');console.error('database_failure',response.status,path.split('?')[0],data?.code);fail(503,'DATABASE_UNAVAILABLE','Não foi possível guardar essa alteração agora. Tente novamente.');}return data;
}
async function rpc(name:string,args:unknown){return db('rpc/'+name,'POST',args);}
async function rate(req:Request,category:string,limit:number){const ip=req.headers.get('x-forwarded-for')?.split(',')[0]?.trim()||req.headers.get('cf-connecting-ip')||'unknown';const bucket=await digest(env('RATE_LIMIT_SALT')+':'+category+':'+ip);if(!await rpc('lk_allow',{p_bucket:bucket,p_limit:limit}))fail(429,'RATE_LIMITED','Vamos fazer uma pequena pausa. Tente novamente em alguns minutos.');}
async function owner(req:Request,id:unknown){if(!uuid(id))fail(404,'NOT_FOUND','Presente não encontrado.');let g:any=null;const token=req.headers.get('x-edit-token')||'';if(/^[a-f0-9]{64}$/.test(token))g=(await db('lk_gifts?id=eq.'+id+'&edit_token_hash=eq.'+await digest(token)+'&select=*'))[0];else{const user=await authUser(req,false);if(user)g=(await db('lk_gifts?id=eq.'+id+'&owner_user_id=eq.'+user.id))[0];else fail(401,'PRIVATE_ACCESS','Use seu acesso privado ou entre na conta.');}if(!g||g.deleted_at)fail(404,'NOT_FOUND','Este presente não foi encontrado.');if(g.owner_user_id&&(await db('lk_profiles?id=eq.'+g.owner_user_id+'&disabled=eq.true&select=id')).length)fail(403,'ACCOUNT_PAUSED','Esta conta está pausada.');return g;}
async function sign(bucket:string,path:string){const r=await fetch(root+'/storage/v1/object/sign/'+bucket+'/'+path,{method:'POST',headers:{apikey:key,Authorization:'Bearer '+key,'Content-Type':'application/json'},body:JSON.stringify({expiresIn:3600})});const d=await r.json();if(!r.ok)fail(503,'PHOTO_UNAVAILABLE','Uma das memórias não pôde ser aberta agora.');return root+'/storage/v1'+d.signedURL;}
async function artwork(gift:string,all=false){const rows=await db('lk_image_jobs?gift_id=eq.'+gift+'&status=eq.completed'+(all?'':'&included=eq.true')+'&order=slot.asc');return Promise.all(rows.map(async(a:any)=>({id:a.id,slot:a.slot,url:await sign('love-art',a.storage_path),caption:'Cena '+(a.slot+1)+' · criada com IA',ai:true,included:a.included!==false})));}
async function fullGift(g:any,privateView=false){const [photos,art]=await Promise.all([db('lk_photos?gift_id=eq.'+g.id+'&order=sort_order.asc,created_at.asc'),db('lk_image_jobs?gift_id=eq.'+g.id+'&status=eq.completed&included=eq.true&order=slot.asc')]);const [signedPhotos,signedArt]=await Promise.all([Promise.all(photos.map(async(p:any)=>({id:p.id,url:await sign('love-memories',p.storage_path),caption:p.caption,date:p.taken_at||''}))),Promise.all(art.map(async(a:any)=>({id:a.id,slot:a.slot,url:await sign('love-art',a.storage_path),caption:'Cena '+(a.slot+1)+' · criada com IA',ai:true})))]);const content={...g.content};if(!privateView){delete content.email;delete content.slug;delete content.analytics_session_id;delete content.ai_descriptions;delete content.ai_style;}return {...content,id:g.id,slug:g.slug||g.content.slug||'',format:g.format,theme:g.theme,plan_id:g.plan_id,status:g.status,expires_at:g.expires_at,access_kind:g.access_kind,edit_expires_at:g.edit_expires_at,created_at:g.created_at,updated_at:g.updated_at,frozen:g.frozen,suspended:g.suspended,...(privateView?{checkout_email:g.checkout_email||'',owner_user_id:g.owner_user_id,public_consent:g.public_consent,deleted_at:g.deleted_at}:{}),photos:signedPhotos,illustrations:signedArt};}
function cleanGift(input:any){
 if(!input||typeof input!=='object'||!['album','retrospectiva','ambos'].includes(input.format)||!['eucalipto','poesia','estrelas','solar'].includes(input.theme))fail(400,'INVALID_FORMAT','Escolha um dos formatos e temas disponíveis.');
 const content:any={};for(const [k,max] of Object.entries({sender:60,recipient:60,occasion:100,story:4000,letter:12000,music_title:140,music_url:600,illustration_brief:1500,email:254,slug:80,place:150,first_memory:1500,promise:1500,dedication:300}))content[k]=text(input[k]??'',max);
 content.start_date=text(input.start_date||'',10);if(content.start_date&&(!/^\d{4}-\d{2}-\d{2}$/.test(content.start_date)||!Number.isFinite(Date.parse(content.start_date))||new Date(content.start_date).toISOString().slice(0,10)!==content.start_date||content.start_date>new Date().toISOString().slice(0,10)))fail(400,'INVALID_DATE','Confira a data em que essa história começou.');
 content.start_time=text(input.start_time||'',5);if(content.start_time&&!/^(?:[01]\d|2[0-3]):[0-5]\d$/.test(content.start_time))fail(400,'INVALID_TIME','Confira o horário do começo da história.');if(content.start_date&&Date.parse(content.start_date+'T'+(content.start_time||'00:00')+':00-03:00')>Date.now())fail(400,'INVALID_DATE','O começo da história precisa estar no passado.');
 content.album_music_enabled=input.album_music_enabled!==false;
 content.ai_style=Object.hasOwn(AI_STYLE_PROMPTS,input.ai_style)?input.ai_style:'storybook';const scenes=input.ai_descriptions||[];if(!Array.isArray(scenes)||scenes.length>4)fail(400,'AI_SCENE_INVALID','Descreva até quatro cenas.');content.ai_descriptions=scenes.map(v=>text(v,1000));
 if(content.music_url){let u:URL;try{u=new URL(content.music_url);}catch{fail(400,'INVALID_MUSIC','Use um link do YouTube ou Spotify.');}if(u!.protocol!=='https:'||!['open.spotify.com','www.youtube.com','youtube.com','youtu.be','music.youtube.com'].includes(u!.hostname))fail(400,'INVALID_MUSIC','Use um link HTTPS do YouTube ou Spotify.');}
 for(const [field,max] of [['reasons',20],['coupons',10],['dreams',20],['achievements',20]] as const){const items=input[field]||[];if(!Array.isArray(items)||items.length>max)fail(400,'CONTENT_LIMIT','Há conteúdo demais nesta seção.');content[field]=items.map(x=>text(x,500)).filter(Boolean);}
 if(!Array.isArray(input.open_when)||input.open_when.length>3)fail(400,'CONTENT_LIMIT','Use até 3 cartas especiais.');content.open_when=input.open_when.map((x:any)=>({title:text(x.title,100),text:text(x.text,3000)})).filter((x:any)=>x.title&&x.text);
 content.analytics_session_id=uuid(input.analytics_session_id)?input.analytics_session_id:null;
 if(input.music_track){const t=input.music_track;if(t.provider==='original'&&t.id==='koala-theme'){content.music_track={provider:'original',id:'koala-theme',title:'Nosso pequeno infinito',artist:'LoveKoala · instrumental original',url:'',artwork:''};content.music_url='';content.music_title='Nosso pequeno infinito';}else{const parsed=parseSongUrl(content.music_url);if(parsed.id!==t.id||parsed.provider!==t.provider)fail(400,'MUSIC_INVALID','Confira a música selecionada.');content.music_track={...parsed,title:text(t.title||content.music_title,140),artist:text(t.artist||'',140),artwork:parsed.provider==='youtube'?'https://i.ytimg.com/vi/'+parsed.id+'/hqdefault.jpg':/^https:\/\/(i\.scdn\.co|image-cdn-[a-z0-9-]+\.spotifycdn\.com)\//.test(t.artwork||'')?text(t.artwork,600):''};}}
 content.stats_consent=input.stats_consent===true;content.scratch_message=text(input.scratch_message||'',300);for(const [field,allowed,defaults] of [['selected_games',['memory','connect','wheel'],['memory','connect','wheel']],['decorations',['hearts','stars','petals','fireflies','paperplanes'],['hearts','stars']]] as const){const list=input[field]??defaults;if(!Array.isArray(list)||list.length>allowed.length||list.some((v:any)=>!(allowed as readonly string[]).includes(v)))fail(400,'FEATURE_INVALID','Escolha somente os elementos disponíveis.');content[field]=[...new Set(list)];}
 content.billing_cycle=input.billing_cycle==='monthly'?'monthly':'once';content.editor_version=2;
 for(const field of ['milestones','places','quiz','section_selection']){if(input[field]!==undefined&&(!Array.isArray(input[field])||input[field].length>(field==='quiz'?5:field==='section_selection'?17:12)))fail(400,'CONTENT_LIMIT','Confira o limite de itens desta seção.');}
 content.milestones=(input.milestones||[]).map((m:any)=>{if(!m||typeof m!=='object')fail(400,'INVALID_CONTENT','Confira um dos marcos.');const date=text(m.date||'',10);if(date&&(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(Date.parse(date))||new Date(date).toISOString().slice(0,10)!==date))fail(400,'INVALID_DATE','Confira a data de um dos marcos.');return {title:text(m.title||'',120),date,description:text(m.description||'',1000)};});
 content.places=(input.places||[]).map((p:any)=>{if(!p||typeof p!=='object')fail(400,'INVALID_CONTENT','Confira um dos lugares.');return {name:text(p.name||'',150),note:text(p.note||'',1000)};});
 content.quiz=(input.quiz||[]).map((q:any)=>{if(!q||!Array.isArray(q.options)||q.options.length<2||q.options.length>4||!Number.isInteger(q.answer)||q.answer<0||q.answer>=q.options.length)fail(400,'INVALID_QUIZ','Confira as alternativas e a resposta do quiz.');return {question:text(q.question||'',250),options:q.options.map((v:any)=>text(v,200)),answer:q.answer};});
 const sections=['song','about','letter','photos','start','timeline','reasons','places','achievements','dreams','letters','coupons','quiz','night','stats','games','ending'];content.section_selection=[...new Set((input.section_selection||[]).map((v:any)=>{if(!sections.includes(v))fail(400,'INVALID_SECTION','Escolha um capítulo disponível.');return v;}))];
 if(encoder.encode(JSON.stringify(content)).byteLength>90000)fail(400,'CONTENT_LIMIT','Sua história está muito longa. Reduza um pouco os textos para continuar.');
 if(!Array.isArray(input.photos)||input.photos.length>80)fail(400,'PHOTO_LIMIT','O limite é de 80 fotos.');
 return {format:input.format,theme:input.theme,plan_id:text(input.plan_id||'encanto',30),content};
}
async function save(req:Request,body:any){const g=await owner(req,body.gift_id);assertEditable(g);const clean=cleanGift(body.gift);const plans=await db('lk_plans?id=eq.'+encodeURIComponent(g.status==='draft'?clean.plan_id:g.plan_id)+'&active=eq.true');const plan=plans[0];if(!plan)fail(400,'PLAN_INVALID','Escolha um dos planos disponíveis.');if(g.status!=='draft'&&(!plan.formats.includes(clean.format)||body.gift.photos.length>plan.max_photos))fail(400,'PLAN_LIMIT','O conteúdo precisa respeitar o plano adquirido.');if(g.status!=='draft'){clean.plan_id=g.plan_id;const art=await db('lk_image_jobs?gift_id=eq.'+g.id+'&select=id&limit=1');if(art.length&&clean.theme!==g.theme)fail(409,'THEME_LOCKED','O tema já foi usado nas ilustrações. Mantenha esse tema para preservar o conjunto.');}
 const user=await authUser(req,false);if(user&&g.owner_user_id&&g.owner_user_id!==user.id)fail(403,'GIFT_OWNER','Este presente pertence a outra conta.');
 if(user&&!g.owner_user_id)await rpc('lk_claim_gift_owner',{p_gift:g.id,p_owner:user.id});
 if(g.checkout_email&&(await db('lk_orders?gift_id=eq.'+g.id+'&status=in.(created,pending,uncertain,paid)&select=id&limit=1')).length)clean.content.email=g.checkout_email;
 await db('lk_gifts?id=eq.'+g.id,'PATCH',{...clean,updated_at:new Date().toISOString()});
 await Promise.all(body.gift.photos.map((p:any,i:number)=>{if(!uuid(p.id))fail(400,'PHOTO_INVALID','Uma das fotos não foi identificada.');return db('lk_photos?id=eq.'+p.id+'&gift_id=eq.'+g.id,'PATCH',{caption:text(p.caption||'',500),sort_order:i});}));return {ok:true};
}
async function upload(req:Request){allowedOrigin(req);await rate(req,'upload',250);if(Number(req.headers.get('content-length')||0)>7*1024*1024)fail(413,'FILE_LIMIT','A foto é grande demais.');const form=await req.formData();const g=await owner(req,form.get('gift_id'));assertEditable(g);const f=form.get('file');if(!(f instanceof File)||f.size>6*1024*1024||!f.size)fail(400,'FILE_INVALID','Envie uma imagem de até 6 MB.');const bytes=new Uint8Array(await (f as File).arrayBuffer());const sig=Array.from(bytes.slice(0,12));const jpeg=sig[0]===255&&sig[1]===216&&sig[2]===255,png=sig.slice(0,8).join(',')==='137,80,78,71,13,10,26,10',webp=new TextDecoder().decode(bytes.slice(0,4))==='RIFF'&&new TextDecoder().decode(bytes.slice(8,12))==='WEBP';const ext=jpeg?'jpg':png?'png':webp?'webp':'';if(!ext)fail(415,'IMAGE_ONLY','Use uma imagem JPG, PNG ou WebP.');const path=g.id+'/'+crypto.randomUUID()+'.'+ext;const p=await rpc('lk_add_photo',{p_gift:g.id,p_path:path});try{const r=await fetch(root+'/storage/v1/object/love-memories/'+path,{method:'POST',headers:{apikey:key,Authorization:'Bearer '+key,'Content-Type':jpeg?'image/jpeg':png?'image/png':'image/webp','x-upsert':'false'},body:bytes});if(!r.ok)throw new Error('storage');return {id:p.id,url:await sign('love-memories',path),caption:'',date:''};}catch{await db('lk_photos?id=eq.'+p.id,'DELETE');fail(503,'UPLOAD_FAILED','Não consegui guardar essa foto. Tente de novo.');}}
function stripeForm(data:any,prefix=''):URLSearchParams{const params=new URLSearchParams();function add(v:any,k:string){if(v===null||v===undefined)return;if(typeof v==='object'){for(const [sub,x] of Object.entries(v))add(x,k?`${k}[${sub}]`:sub);}else params.append(k,String(v));}add(data,prefix);return params;}
async function stripe(path:string,method='GET',data?:unknown,idempotency?:string){const r=await fetch('https://api.stripe.com/v1/'+path,{method,headers:{Authorization:'Bearer '+env('STRIPE_SECRET_KEY'),...(data?{'Content-Type':'application/x-www-form-urlencoded'}:{}),...(idempotency?{'Idempotency-Key':idempotency}:{})},body:data?stripeForm(data):undefined,signal:AbortSignal.timeout(20000)});const d=await r.json();if(!r.ok)fail(502,'PAYMENT_PROVIDER','O serviço de cartão não concluiu a operação. Tente novamente mais tarde.');return d;}
async function mercosul(path:string,method='GET',data?:unknown,idempotency?:string){const r=await fetch((env('MERCOSULPAY_API_BASE')||'https://mercosulpay.com/api/public/v1')+path,{method,headers:{Authorization:'Bearer '+env('MERCOSULPAY_API_KEY'),'Content-Type':'application/json',...(idempotency?{'Idempotency-Key':idempotency}:{})},body:data?JSON.stringify(data):undefined,signal:AbortSignal.timeout(20000)});const d=await r.json();if(!r.ok)fail(502,'PIX_PROVIDER','O serviço de Pix não concluiu a operação. Tente novamente mais tarde.');return d.data||d;}
function orderView(o:any){return {id:o.id,plan_id:o.plan_id,access_kind:o.access_kind,access_days_snapshot:o.access_days_snapshot,billing_cycle:o.billing_cycle,purpose:o.purpose,provider:o.provider,status:o.status,amount_cents:o.amount_cents,checkout_url:o.checkout_url,pix_code:o.pix_code,expires_at:o.expires_at};}
const PRODUCTION_URL='https://lovekoala.com.br';
const PRODUCTION_WEBHOOK_BASE=PRODUCTION_URL+'/api/webhooks';
const STRIPE_EVENTS=['checkout.session.completed','checkout.session.async_payment_succeeded','checkout.session.expired','charge.refunded','invoice.paid','invoice.payment_failed','customer.subscription.updated','customer.subscription.deleted'];
async function paymentWebhookBase(){const value=await rpc('lk_payment_webhook_base',{});return value===PRODUCTION_WEBHOOK_BASE?value:root+'/functions/v1/lovekoala-api/webhook';}
async function productionProbes(){return Promise.all(['stripe','mercosulpay'].map(async provider=>{
 const url=PRODUCTION_WEBHOOK_BASE+'/'+provider;
 try{const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}',redirect:'error',signal:AbortSignal.timeout(10000)});const data=await r.json().catch(()=>({}));return {provider,url,ready:r.status===401&&data.code==='BAD_SIGNATURE'&&r.headers.get('x-lovekoala-webhook')===provider};}
 catch{return {provider,url,ready:false};}
}));}
async function loveKoalaStripeHook(){const result=await stripe('webhook_endpoints?limit=100');return result.data?.find((h:any)=>[root+'/functions/v1/lovekoala-api/webhook/stripe',PRODUCTION_WEBHOOK_BASE+'/stripe'].includes(h.url)&&h.status==='enabled');}
async function productionAction(user:any,b:any){
 const base=await paymentWebhookBase();
 if(b.action==='admin_production_status'){
  const hook=env('STRIPE_SECRET_KEY')?await loveKoalaStripeHook():null;
  return {site_url:PRODUCTION_URL,environment_site_url:env('SITE_URL'),production_url:PRODUCTION_URL,webhook_base:base,custom_domain_active:base===PRODUCTION_WEBHOOK_BASE,stripe_url:hook?.url||null,stripe_events_ready:!!hook&&STRIPE_EVENTS.every(e=>hook.enabled_events?.includes(e)||hook.enabled_events?.includes('*')),checks:b.verify===true?await productionProbes():[]};
 }
 const checks=await productionProbes();
 if(checks.some(c=>!c.ready))fail(409,'DOMAIN_NOT_READY','Publique o projeto no EasyPanel com HTTPS em lovekoala.com.br antes de ativar os webhooks. Os endpoints atuais continuam funcionando.');
 if(!env('STRIPE_SECRET_KEY')||!env('STRIPE_WEBHOOK_SECRET'))fail(503,'CARD_UNAVAILABLE','Configure as chaves do cartão no Supabase antes de ativar o domínio.');
 const target=await loveKoalaStripeHook();if(!target)fail(404,'WEBHOOK_NOT_FOUND','Configure primeiro o webhook dedicado do LoveKoala no Stripe.');
 await stripe('webhook_endpoints/'+target.id,'POST',{url:PRODUCTION_WEBHOOK_BASE+'/stripe',enabled_events:target.enabled_events?.includes('*')?['*']:[...new Set([...(target.enabled_events||[]),...STRIPE_EVENTS])]});
 await rpc('lk_set_payment_webhook_base',{p_value:PRODUCTION_WEBHOOK_BASE});
 await audit(user,'production_webhooks_activated',PRODUCTION_URL);
 return {ok:true,webhook_base:PRODUCTION_WEBHOOK_BASE,checks};
}
