 if(!valid)fail(401,'BAD_SIGNATURE','Assinatura inválida.');let payload:any;try{payload=JSON.parse(raw);}catch{fail(400,'INVALID_JSON','Evento inválido.');}delivery=provider==='stripe'?payload.id:delivery;event=provider==='stripe'?payload.type:event;if(typeof delivery!=='string'||!delivery||delivery.length>180)fail(400,'INVALID_EVENT','Evento inválido.');const hash=await digest(raw);const prior=(await db('lk_payment_events?provider=eq.'+provider+'&event_id=eq.'+encodeURIComponent(delivery)))[0];if(prior&&prior.payload_hash!==hash)fail(409,'EVENT_CONFLICT','Evento divergente.');if(prior?.status==='processed')return {received:true};if(!prior)await db('lk_payment_events?on_conflict=provider,event_id','POST',{provider,event_id:delivery,payload_hash:hash});
 const d=payload.data?.object||payload.data||payload;let handled=false;
 if(provider==='stripe'&&['checkout.session.completed','checkout.session.async_payment_succeeded','checkout.session.expired'].includes(event)&&d.metadata?.application==='lovekoala'){const o=(await db('lk_orders?provider=eq.stripe&provider_id=eq.'+encodeURIComponent(d.id)))[0];if(o){await reconcile(o);handled=true;}}
 if(provider==='stripe'&&['invoice.paid','invoice.payment_failed','customer.subscription.updated','customer.subscription.deleted'].includes(event)){const sid=event.startsWith('invoice.')?(typeof d.subscription==='string'?d.subscription:d.subscription?.id||d.parent?.subscription_details?.subscription):d.id;if(typeof sid==='string'){const sub=(await db('lk_subscriptions?provider_subscription_id=eq.'+encodeURIComponent(sid)))[0];if(sub){await syncStripeSubscription(sid,sub.gift_id,event.startsWith('invoice.')?d.id:undefined);await rpc('lk_freeze_expired',{});handled=true;}}}
 if(provider==='mercosulpay'&&event==='pix.received'&&typeof d.id==='string'){const o=(await db('lk_orders?provider=eq.mercosulpay&provider_id=eq.'+encodeURIComponent(d.id)))[0];if(o){await reconcile(o);handled=true;}}
 if(provider==='stripe'&&event==='charge.refunded'&&typeof d.payment_intent==='string'){const o=(await db('lk_orders?provider=eq.stripe&provider_payment_intent=eq.'+encodeURIComponent(d.payment_intent)))[0];if(o&&d.amount_refunded>=o.amount_cents&&String(d.currency).toLowerCase()==='brl'){await rpc('lk_refund_order',{p_order:o.id});handled=true;}}
 await db('lk_payment_events?provider=eq.'+provider+'&event_id=eq.'+encodeURIComponent(delivery),'PATCH',{status:handled?'processed':'ignored'});return {received:true};
