async function uploadAiReference(req:Request){allowedOrigin(req);await rate(req,'ai_reference',20);if(Number(req.headers.get('content-length')||0)>1200000)fail(413,'REFERENCE_SIZE','Envie uma referência de até 1 MB.');const form=await req.formData();const {g}=await aiGift(req,form.get('gift_id'));if(form.get('consent')!=='true')fail(400,'AI_CONSENT','Confirme que tem permissão para usar as fotos de referência.');const subject=form.get('subject');if(!['sender','recipient'].includes(String(subject)))fail(400,'REFERENCE_SUBJECT','Escolha de quem é esta referência.');if((await aiJobs(g.id)).some(j=>j.status==='running'))fail(409,'AI_BUSY','Espere a imagem terminar antes de mudar as referências.');const file=form.get('file');if(!(file instanceof File)||file.size>1048576||!file.size)fail(400,'REFERENCE_SIZE','Envie uma referência de até 1 MB.');const bytes=new Uint8Array(await (file as File).arrayBuffer());const mime=bytes[0]===255&&bytes[1]===216&&bytes[2]===255?'image/jpeg':bytes.slice(0,8).join(',')==='137,80,78,71,13,10,26,10'?'image/png':new TextDecoder().decode(bytes.slice(0,4))==='RIFF'&&new TextDecoder().decode(bytes.slice(8,12))==='WEBP'?'image/webp':'';if(!mime)fail(415,'IMAGE_ONLY','Use uma foto JPG, PNG ou WebP.');const path=g.id+'/'+crypto.randomUUID()+'.'+(mime==='image/jpeg'?'jpg':mime.split('/')[1]);const old=(await aiReferences(g.id)).find(r=>r.subject===subject);const response=await fetch(root+'/storage/v1/object/love-ai-references/'+path,{method:'POST',headers:{apikey:key,Authorization:'Bearer '+key,'Content-Type':mime,'x-upsert':'false'},body:bytes,signal:AbortSignal.timeout(12000)});if(!response.ok)fail(503,'REFERENCE_UPLOAD','Não foi possível guardar a referência. Tente novamente.');try{if(old)await db('lk_ai_references?id=eq.'+old.id,'PATCH',{storage_path:path,mime,consent_at:new Date().toISOString()});else await db('lk_ai_references','POST',{gift_id:g.id,subject,storage_path:path,mime,consent_at:new Date().toISOString()});}catch(e){await removeStorage('love-ai-references',[path]);throw e;}if(old)await removeStorage('love-ai-references',[old.storage_path]);await invalidateAiScenes(g.id);return {ok:true};}
