async function generate(g:any,slot:number){assertImagesEnabled();if(!aiReadiness().images)fail(503,'ART_UNAVAILABLE','A geração de imagens está em preparação. Você pode montar e publicar o presente normalmente.');if(!Number.isInteger(slot)||slot<0||slot>3)fail(400,'IMAGE_SLOT','Escolha uma das quatro cenas.');if(!accessReady(g)||!['encanto','universo'].includes(g.plan_id))fail(402,'PAYMENT_REQUIRED','As imagens com IA são liberadas nos planos elegíveis depois do pagamento.');const refs=await aiReferences(g.id),prepared=(await aiJobs(g.id)).find(j=>j.slot===slot);if(prepared?.status!=='completed'&&prepared?.reference_fingerprint!==await referenceFingerprint(refs))fail(409,'REFERENCE_CHANGED','Prepare a cena novamente para usar as referências atuais.');const claim=await rpc('lk_claim_image',{p_gift:g.id,p_slot:slot});if(!claim.claimed)return {job:jobView(claim.job)};const job=claim.job;
 const task=(async()=>{let path='';try{const response=await fetch(imageEndpoint(),{method:'POST',headers:{Authorization:'Bearer '+env('NVIDIA_IMAGE_API_KEY'),'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify({prompt:job.prompt,mode:'base',steps:40,cfg_scale:3.5,width:1024,height:1024,samples:1,seed:crypto.getRandomValues(new Uint32Array(1))[0],disable_safety_checker:false}),redirect:'error',signal:AbortSignal.timeout(115000)});if(!response.ok)throw Error('GENERATION_UNAVAILABLE');const d=await limitedJson(response);const artifact=d.artifacts?.[0];if(artifact?.finishReason==='CONTENT_FILTERED')throw Error('CONTENT_FILTERED');if(artifact?.finishReason!=='SUCCESS'||typeof artifact.base64!=='string'||artifact.base64.length>16*1024*1024)throw Error('GENERATION_UNAVAILABLE');const bytes=Uint8Array.from(atob(artifact.base64),(c:string)=>c.charCodeAt(0));const jpeg=bytes[0]===255&&bytes[1]===216&&bytes[2]===255,png=bytes.slice(0,8).join(',')==='137,80,78,71,13,10,26,10';if(!jpeg&&!png||bytes.length>12*1024*1024)throw Error('GENERATION_UNAVAILABLE');const fresh=(await db('lk_gifts?id=eq.'+g.id))[0];if(!accessReady(fresh))throw Error('GIFT_UNAVAILABLE');path=g.id+'/'+job.id+'.'+(jpeg?'jpg':'png');const r=await fetch(root+'/storage/v1/object/love-art/'+path,{method:'POST',headers:{apikey:key,Authorization:'Bearer '+key,'Content-Type':jpeg?'image/jpeg':'image/png','x-upsert':'true'},body:bytes,signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('STORAGE_FAILED');const updated=await db('lk_image_jobs?id=eq.'+job.id+'&run_id=eq.'+job.run_id+'&status=eq.running','PATCH',{status:'completed',storage_path:path,completed_at:new Date().toISOString(),updated_at:new Date().toISOString()});if(!updated.length)await removeStorage('love-art',[path]);}catch(e){const code=e instanceof Error&&['CONTENT_FILTERED','GIFT_UNAVAILABLE','STORAGE_FAILED'].includes(e.message)?e.message:'GENERATION_UNAVAILABLE';await db('lk_image_jobs?id=eq.'+job.id+'&run_id=eq.'+job.run_id+'&status=eq.running','PATCH',{status:'failed',error_code:code,updated_at:new Date().toISOString()});}})();EdgeRuntime.waitUntil(task);return {job:jobView(job)};
}
const KOALA_DESTINATIONS=['create','plans','examples','how','faq','account','checkout'];
function koalaNavigation(value:any,question:string,page:string){
 if(!value||!KOALA_DESTINATIONS.includes(value.destination))return null;
 const normalized=question.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 const refused=/\b(nao|nunca)\b.{0,45}\b(abra|abrir|abre|mude|mudar|navegue|navegar|leve|levar|va|ir|mostre|mostrar)\b|\b(?:so|apenas) (?:quero )?(?:saber|entender|explique|explique-me)\b/.test(normalized);
 const requested=/\b(?:abra|abrir|abre|mostra|mostre|leve|levar|va|vamos|quero (?:comprar|criar|ver|abrir|ir)|pode me (?:levar|mostrar)|me (?:leva|mostra))\b/.test(normalized);
 return {destination:value.destination==='checkout'&&page!=='create'?'create':value.destination,format:['album','retrospectiva','ambos'].includes(value.format)?value.format:'album',plan:['carinho','encanto','universo'].includes(value.plan)?value.plan:'',automatic:requested&&!refused};
}
const KOALA_TOOL={type:'function',function:{name:'navigate_lovekoala',description:'Ofereça um atalho ou abra uma página interna do LoveKoala para atender ao pedido da pessoa. Não compra, não publica e não altera dados. Use no máximo uma vez por resposta.',parameters:{type:'object',properties:{destination:{type:'string',enum:KOALA_DESTINATIONS},format:{type:'string',enum:['album','retrospectiva','ambos']},plan:{type:'string',enum:['carinho','encanto','universo']}},required:['destination'],additionalProperties:false}}};
