 if(b.action==='club_balance')return await rpc('lk_club_balance',{p_owner:user.id});
 if(b.action==='my_gift_preview'){const g=await owner(req,b.gift_id);if(g.owner_user_id!==user.id)fail(403,'GIFT_OWNER','Este presente pertence a outra conta.');return {gift:await fullGift(g,true)};}
