function parseSongUrl(raw:string){let u:URL;try{u=new URL(raw);}catch{fail(400,'MUSIC_URL','Use um link do YouTube ou Spotify.');}if(u!.protocol!=='https:')fail(400,'MUSIC_URL','Use um link HTTPS.');let id='';if(u!.hostname==='youtu.be')id=u!.pathname.slice(1);else if(['youtube.com','www.youtube.com','music.youtube.com'].includes(u!.hostname)){if(u!.pathname==='/watch')id=u!.searchParams.get('v')||'';else if(/^\/(embed|shorts)\//.test(u!.pathname))id=u!.pathname.split('/')[2]||'';}if(/^[a-zA-Z0-9_-]{11}$/.test(id))return {provider:'youtube',id,url:'https://www.youtube.com/watch?v='+id};if(u!.hostname==='open.spotify.com'){const m=u!.pathname.match(/^\/(?:intl-[a-z]+\/)?(track|album|playlist|episode)\/([a-zA-Z0-9]+)\/?$/);if(m)return {provider:'spotify',id:m[1]+'/'+m[2],url:'https://open.spotify.com/'+m[1]+'/'+m[2]};}fail(400,'MUSIC_URL','Escolha um link de música válido.');}
async function mailConfig(){const stored=await rpc('lk_get_mail_config',{});const api_key=env('RESEND_API_KEY')||stored.api_key||'';const from=env('EMAIL_FROM')||stored.from||'';const enabled=env('RESEND_API_KEY')?env('EMAIL_ENABLED')==='true':stored.enabled===true;return {api_key,from,enabled,ready:!!api_key&&!!from&&enabled,environment:!!env('RESEND_API_KEY')};}
const htmlEscape=(s:any)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
function summaryMessage(r:any,from:string){const s=r.summary;const link=r.guest_resume_url||r.resume_origin+'/criar?id='+r.gift_id+'&continuar=1';const accessNote=r.guest_resume_url?'Este link é privado e permite retomar seu presente. Crie a conta ou entre depois de pagar.':'Entre com a conta que criou o presente.';const format=s.format==='ambos'?'Álbum + retrospectiva':s.format==='album'?'Álbum interativo':'Retrospectiva';const price=(r.amount_cents/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})+(r.billing_cycle==='monthly'?' / mês':' · pagamento único');return {from,to:[r.email],subject:'Sua história no LoveKoala está guardada ♡',text:`Seu presente continua salvo.\n\n${s.sender} & ${s.recipient}\n${format}\nPlano ${s.plan_name} · ${price}\n${s.photos} fotos\n\nContinue de onde parou: ${link}\n${accessNote} Confira o valor antes de pagar. Se você já concluiu, pode ignorar este resumo.\n\nVocê pediu este resumo ao preparar seu presente. Não é uma assinatura de e-mails.`,html:`<div style="background:#f5effb;padding:36px 16px;font-family:Arial,sans-serif;color:#32213e"><div style="max-width:520px;margin:auto;background:#fff;border-radius:24px;padding:36px"><p style="color:#8250a3;font-size:14px;letter-spacing:2px">LOVEKOALA ♡</p><h1 style="font-size:30px;line-height:1.2">O carinho pode<br>esperar um pouquinho.</h1><p style="color:#6c5a77;line-height:1.7">Sua história continua guardada. Quando quiser, volte para terminar a surpresa.</p><div style="padding:22px;background:#f8f2fc;border-radius:16px;margin:24px 0"><h2 style="font-size:21px;margin:0 0 14px">${htmlEscape(s.sender)} &amp; ${htmlEscape(s.recipient)}</h2><p>${htmlEscape(format)} · Plano ${htmlEscape(s.plan_name)}</p><p>${htmlEscape(price)}<br>${htmlEscape(s.photos)} fotos na sua história</p></div><a href="${htmlEscape(link)}" style="background:#8750b2;color:white;display:block;text-align:center;padding:17px;border-radius:30px;text-decoration:none;font-weight:bold">Continuar meu presente →</a><p style="font-size:12px;color:#766680;line-height:1.8">${htmlEscape(accessNote)} Confira o valor antes de pagar. Se já concluiu, pode ignorar este resumo.</p><hr style="border:0;border-top:1px solid #eee5f3;margin:24px 0"><p style="font-size:11px;line-height:1.8;color:#897894">Você solicitou este resumo. Isso não adiciona seu e-mail a uma lista de campanhas.</p></div></div>`};}
async function captureCheckout(o:any,origin:string,consent:boolean|null=null,reason='checkout_started'){return rpc('lk_capture_checkout',{p_order:o.id,p_origin:origin,p_consent:consent,p_reason:reason});}
async function sendSummary(id:string){const config=await mailConfig();const before=(await db('lk_checkout_recovery?id=eq.'+id))[0];if(!before||!before.email_consent||before.status==='recovered'||before.email_status==='sent')return {status:before?.email_status||'skipped'};const order=(await db('lk_orders?id=eq.'+before.order_id))[0];if(!order)return {status:'skipped'};const verified=await reconcile(order);if(verified.status==='paid')return {status:'skipped'};if(!config.ready){await db('lk_checkout_recovery?id=eq.'+id,'PATCH',{email_status:'unavailable',last_error:'EMAIL_NOT_CONFIGURED'});return {status:'unavailable'};}
 const claim=await rpc('lk_take_summary',{p_id:id});if(!claim.claimed)return {status:before.email_status};const r=claim.record;if(!r.message_payload){const gift=(await db('lk_gifts?id=eq.'+r.gift_id+'&select=owner_user_id'))[0];if(gift&&!gift.owner_user_id){const resume=secretToken();await db('lk_guest_resumes','POST',{gift_id:r.gift_id,token_hash:await digest(resume)});r.guest_resume_url=r.resume_origin+'/criar?id='+r.gift_id+'&continuar=1#retomar='+resume;}}const payload=r.message_payload||summaryMessage(r,config.from);if(!r.message_payload)await db('lk_checkout_recovery?id=eq.'+id,'PATCH',{message_payload:payload});const idempotency='lk-summary-'+r.id+'-'+(await digest(r.email_requested_at)).slice(0,20);
 try{const response=await fetch('https://api.resend.com/emails',{method:'POST',headers:{Authorization:'Bearer '+config.api_key,'Content-Type':'application/json','Idempotency-Key':idempotency},body:JSON.stringify(payload),signal:AbortSignal.timeout(12000)});const result=await response.json();if(!response.ok||typeof result.id!=='string')throw Error('EMAIL_PROVIDER');await db('lk_checkout_recovery?id=eq.'+id,'PATCH',{email_status:'sent',sent_at:new Date().toISOString(),provider_message_id:result.id,last_error:null});return {status:'sent'};}catch{await db('lk_checkout_recovery?id=eq.'+id,'PATCH',{email_status:'failed',last_error:'EMAIL_PROVIDER',scheduled_at:new Date(Date.now()+5*60000).toISOString()});return {status:'failed'};}}
async function summaryQueue(){await rpc('lk_mark_abandoned',{});const rows=await db('lk_checkout_recovery?email_consent=eq.true&status=neq.recovered&email_status=in.(queued,failed,sending)&attempts=lt.3&scheduled_at=lte.'+encodeURIComponent(new Date().toISOString())+'&order=scheduled_at.asc&limit=3');const result=await Promise.all(rows.map(async(r:any)=>{try{return await sendSummary(r.id);}catch{return {status:'failed'};}}));return {processed:result.length,sent:result.filter(r=>r.status==='sent').length};}
async function recoveryAction(req:Request,b:any){const origin=allowedOrigin(req);const g=await owner(req,b.gift_id);if(!uuid(b.order_id))fail(400,'ORDER_INVALID','Cobrança inválida.');const o=(await db('lk_orders?id=eq.'+b.order_id+'&gift_id=eq.'+g.id))[0];if(!o)fail(404,'ORDER_NOT_FOUND','Cobrança não encontrada.');if(b.action==='checkout_exit'){await rate(req,'checkout_exit',200);const reason=['stripe_return','pix_closed','left_editor'].includes(b.reason)?b.reason:'left_editor';const record=await captureCheckout(o,origin,null,reason);return {saved:true,status:record.status};}
 if(b.action==='request_summary_email'){const user=await authUser(req,false);if(g.owner_user_id&&g.owner_user_id!==user?.id)fail(401,'LOGIN_REQUIRED','Entre na sua conta para pedir o resumo deste presente.');await rate(req,'summary_email',6);if(!await rpc('lk_allow',{p_bucket:await digest('summary:'+g.id),p_limit:3}))fail(429,'EMAIL_LIMIT','Seu resumo já foi solicitado. Aguarde um pouco antes de tentar de novo.');if(b.consent!==true)fail(400,'EMAIL_CONSENT','Confirme que deseja receber este resumo.');const email=text(b.email||g.content.email,254,true);if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))fail(400,'EMAIL_INVALID','Confira o e-mail do resumo.');if(!g.owner_user_id&&email.toLowerCase()!==(g.checkout_email||g.content.email||'').toLowerCase())fail(400,'CHECKOUT_EMAIL_REQUIRED','Use o e-mail informado no pagamento para receber a retomada privada.');const record=await captureCheckout(o,origin,true,'summary_requested');if(record.status!=='recovered'&&record.email!==email){await db('lk_checkout_recovery?id=eq.'+record.id,'PATCH',{email,email_consent:true,consented_at:new Date().toISOString(),email_status:'queued',attempts:0,email_requested_at:new Date().toISOString(),scheduled_at:new Date().toISOString(),message_payload:null});record.email_status='queued';}if(record.status==='recovered')return {saved:true,email_status:'skipped'};if(record.email_status!=='sent')await db('lk_checkout_recovery?id=eq.'+record.id,'PATCH',{scheduled_at:new Date().toISOString()});const sent=await sendSummary(record.id);return {saved:true,email_status:sent.status,resume_url:origin+'/criar?id='+g.id+'&continuar=1'};}
 if(b.action==='cancel_order'){await rate(req,'cancel_order',12);let current=await reconcile(o);if(current.status==='paid'||current.status==='failed')return {order:orderView(current)};if(o.provider!=='stripe'||!o.provider_id)fail(409,'ORDER_STILL_PENDING','Esta cobrança continua pendente. Você pode guardar o link e continuar depois.');const expired=await stripe('checkout/sessions/'+encodeURIComponent(o.provider_id)+'/expire','POST',{});if(expired.status!=='expired')fail(409,'ORDER_STILL_PENDING','A cobrança ainda está sendo conferida.');await db('lk_orders?id=eq.'+o.id,'PATCH',{status:'failed'});await captureCheckout(o,origin,null,'stripe_return');return {order:orderView({...o,status:'failed'})};}fail(400,'ACTION','Ação inválida.');}
async function musicKey(){return env('YOUTUBE_API_KEY')||await rpc('lk_music_key',{})||'';}
// Public search reads metadata only. No cookies, account, player bypass or remote script execution.
const publicMusicCache=new Map<string,{until:number;result:any}>();
function youtubeInitialData(html:string){
 const marker=/(?:var\s+ytInitialData|window\["ytInitialData"\]|ytInitialData)\s*=\s*/g;let match:RegExpExecArray|null;
 while((match=marker.exec(html))){let at=marker.lastIndex;while(/\s/.test(html[at]||'')&&at<html.length)at++;if(html[at]!=='{')continue;const start=at;let level=0,quoted=false,escaped=false;
  for(;at<html.length;at++){const char=html[at];if(quoted){if(escaped)escaped=false;else if(char==='\\')escaped=true;else if(char==='"')quoted=false;continue;}if(char==='"'){quoted=true;continue;}if(char==='{')level++;else if(char==='}'&&--level===0){try{return JSON.parse(html.slice(start,at+1));}catch{break;}}}
 }
 fail(503,'MUSIC_SEARCH','A busca do YouTube não respondeu agora. Tente novamente ou adicione o link da música.');
}
function publicMusicTracks(data:any){
 const root=data?.contents?.twoColumnSearchResultsRenderer?.primaryContents||data?.contents?.sectionListRenderer;if(!root)fail(503,'MUSIC_SEARCH','A busca do YouTube não respondeu agora. Tente novamente ou adicione o link da música.');
 const result:any[]=[],seen=new Set<string>(),stack:any[]=[root];let visited=0;
 const label=(value:any)=>typeof value==='string'?value:typeof value?.simpleText==='string'?value.simpleText:typeof value?.content==='string'?value.content:Array.isArray(value?.runs)?value.runs.map((r:any)=>typeof r.text==='string'?r.text:'').join(''):'';
 while(stack.length&&visited++<100000&&result.length<30){const node=stack.pop();if(!node||typeof node!=='object')continue;if(Array.isArray(node)){stack.push(...[...node].reverse());continue;}
  if(node.adSlotRenderer||node.promotedSparklesWebRenderer||node.searchPyvRenderer)continue;
  const video=node.videoRenderer,lock=node.lockupViewModel;const id=video?.videoId||lock?.contentId;
  if(typeof id==='string'&&/^[a-zA-Z0-9_-]{11}$/.test(id)&&!seen.has(id)){
   const metadata=lock?.metadata?.lockupMetadataViewModel;const title=label(video?.title||metadata?.title).slice(0,140);const artist=label(video?.ownerText||video?.shortBylineText||metadata?.metadata?.contentMetadataViewModel?.metadataRows?.[0]?.metadataParts?.[0]?.text).slice(0,140)||'YouTube';
   if(title){seen.add(id);result.push({provider:'youtube',id,title,artist,artwork:'https://i.ytimg.com/vi/'+id+'/hqdefault.jpg',url:'https://www.youtube.com/watch?v='+id});}continue;
  }
  stack.push(...Object.values(node).reverse());
 }
 return result;
}
async function publicMusicSearch(query:string){
 const cacheKey=query.toLocaleLowerCase('pt-BR');const cached=publicMusicCache.get(cacheKey);if(cached&&cached.until>Date.now())return cached.result;
 const url=new URL('https://www.youtube.com/results');url.searchParams.set('search_query',query);url.searchParams.set('hl','pt');url.searchParams.set('gl','BR');
 let html='';try{const response=await fetch(url,{headers:{'User-Agent':'LoveKoala/1.0','Accept-Language':'pt-BR,pt;q=0.9'},redirect:'error',signal:AbortSignal.timeout(18000)});if(!response.ok||!response.body)throw new Error('SEARCH_UNAVAILABLE');const reader=response.body.getReader(),chunks:Uint8Array[]=[];let length=0;try{for(;;){const {done,value}=await reader.read();if(done)break;length+=value.byteLength;if(length>6*1024*1024)throw new Error('SEARCH_SIZE');chunks.push(value);}}finally{await reader.cancel().catch(()=>{});}const bytes=new Uint8Array(length);let offset=0;for(const chunk of chunks){bytes.set(chunk,offset);offset+=chunk.length;}html=new TextDecoder().decode(bytes);}catch{fail(503,'MUSIC_SEARCH','A busca do YouTube não respondeu agora. Tente novamente ou adicione o link da música.');}
 const tracks=publicMusicTracks(youtubeInitialData(html));const result={tracks,search_mode:'youtube',search_source:'public',search_available:true,next_page_token:null};
 if(publicMusicCache.size>=60)publicMusicCache.delete(publicMusicCache.keys().next().value!);publicMusicCache.set(cacheKey,{until:Date.now()+5*60000,result});return result;
}
async function musicAction(req:Request,b:any){allowedOrigin(req);await rate(req,'music',100);if(b.action==='music_resolve'){const track=parseSongUrl(text(b.url,600,true));const endpoint=track.provider==='youtube'?'https://www.youtube.com/oembed?format=json&url=':'https://open.spotify.com/oembed?url=';const r=await fetch(endpoint+encodeURIComponent(track.url),{signal:AbortSignal.timeout(10000)});if(!r.ok)fail(400,'MUSIC_UNAVAILABLE','Essa música não está disponível para incorporar. Escolha outra.');const data=await r.json();const title=String(data.title||'A música de vocês').slice(0,140);const artwork=track.provider==='youtube'?'https://i.ytimg.com/vi/'+track.id+'/hqdefault.jpg':/^https:\/\/(i\.scdn\.co|image-cdn-[a-z0-9-]+\.spotifycdn\.com)\//.test(data.thumbnail_url||'')?data.thumbnail_url:'';return {track:{...track,title,artist:String(data.author_name||'Spotify').slice(0,140),artwork}};}
 const q=text(b.query||'',120);const youtubeKey=q?await musicKey():'';if(!q){const norm=(v:string)=>v.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const terms=norm(q).split(/\s+/).filter(Boolean);return {tracks:musicCatalog.filter(t=>terms.every(term=>norm(t.title+' '+t.artist).includes(term))),search_mode:'selection',next_page_token:null,search_available:true};}if(!youtubeKey){if(b.page_token)fail(400,'MUSIC_PAGE','Faça uma nova busca pelo nome da música ou artista.');return publicMusicSearch(q);}
 const url=new URL('https://www.googleapis.com/youtube/v3/search');for(const [name,value] of Object.entries({key:youtubeKey,part:'snippet',type:'video',videoEmbeddable:'true',videoSyndicated:'true',maxResults:'25',safeSearch:'moderate',regionCode:'BR',relevanceLanguage:'pt',q}))url.searchParams.set(name,value);const page=text(b.page_token||'',300);if(page&&!/^[a-zA-Z0-9_=-]+$/.test(page))fail(400,'MUSIC_PAGE','A página da busca expirou. Pesquise novamente.');if(page)url.searchParams.set('pageToken',page);const r=await fetch(url,{signal:AbortSignal.timeout(12000)});const data=await r.json();if(!r.ok)fail(503,'MUSIC_SEARCH','A busca do YouTube está indisponível agora. Use a seleção ou adicione um link.');return {tracks:(data.items||[]).filter((v:any)=>/^[a-zA-Z0-9_-]{11}$/.test(v.id?.videoId)).map((v:any)=>({provider:'youtube',id:v.id.videoId,title:String(v.snippet.title).slice(0,140),artist:String(v.snippet.channelTitle).slice(0,140),artwork:'https://i.ytimg.com/vi/'+v.id.videoId+'/hqdefault.jpg',url:'https://www.youtube.com/watch?v='+v.id.videoId})),search_mode:'youtube',search_source:'api',search_available:true,next_page_token:typeof data.nextPageToken==='string'&&/^[a-zA-Z0-9_=-]{1,300}$/.test(data.nextPageToken)?data.nextPageToken:null};
}
async function syncStripeSubscription(id:string,giftId:string,invoiceHint?:string){const gift=(await db('lk_gifts?id=eq.'+giftId+'&select=deleted_at'))[0];if(!gift||gift.deleted_at)return;const s=await stripe('subscriptions/'+encodeURIComponent(id));if(s.metadata?.application!=='lovekoala'||s.metadata?.gift_id!==giftId)fail(409,'PAYMENT_MISMATCH','Assinatura divergente.');const stored=(await db('lk_subscriptions?gift_id=eq.'+giftId))[0];if(!stored)return;const item=s.items?.data?.[0];if(s.items?.data?.length!==1||item?.price?.currency!=='brl'||item.price.unit_amount!==stored.amount_cents||item.price.recurring?.interval!=='month'||item.price.recurring?.interval_count!==1)fail(409,'PAYMENT_MISMATCH','Valor da assinatura divergente.');let start=item.current_period_start||s.current_period_start,end=item.current_period_end||s.current_period_end;let invoice:any=null;const invoiceId=invoiceHint||(typeof s.latest_invoice==='string'?s.latest_invoice:s.latest_invoice?.id);if(invoiceId)invoice=await stripe('invoices/'+encodeURIComponent(invoiceId));let paid=false;if(invoice){const sid=typeof invoice.subscription==='string'?invoice.subscription:invoice.subscription?.id||invoice.parent?.subscription_details?.subscription;paid=invoice.status==='paid'&&invoice.amount_paid===stored.amount_cents&&invoice.currency==='brl'&&sid===s.id;const line=invoice.lines?.data?.find((x:any)=>x.amount===stored.amount_cents&&x.period?.end>x.period?.start);if(paid&&!line)fail(409,'PAYMENT_MISMATCH','Período da assinatura divergente.');if(paid){start=line.period.start;end=line.period.end;}}
 const fresh=await rpc('lk_apply_stripe_cycle',{p_gift:giftId,p_subscription:s.id,p_status:s.status,p_start:new Date(start*1000).toISOString(),p_end:new Date(end*1000).toISOString(),p_amount:stored.amount_cents,p_invoice:paid?invoice.id:null,p_paid:paid,p_cancel:!!s.cancel_at_period_end,p_initial:invoice?.billing_reason==='subscription_create'});if(fresh&&!['subscription_create'].includes(invoice.billing_reason)){const g=(await db('lk_gifts?id=eq.'+giftId))[0];await serverEvent(g,'subscription_renewed',{plan_id:stored.plan_id,provider:'stripe',amount_cents:stored.amount_cents});}}

